import heapq

def match(orders):
    trades = []
    book = {}  # id -> {'side':..., 'price':..., 'qty':..., 'seq':..., 'active':bool}
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def push_order(order_id):
        o = book[order_id]
        if o['side'] == 'buy':
            heapq.heappush(buy_heap, (-o['price'], o['seq'], order_id))
        else:
            heapq.heappush(sell_heap, (o['price'], o['seq'], order_id))

    def top_valid(heap):
        # pop invalid entries from top, return the id of valid top without removing, or None
        while heap:
            item = heap[0]
            oid = item[2]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return oid
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            _, oid = order
            o = book.get(oid)
            if o is not None and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        seq_counter += 1
        my_seq = seq_counter

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            opp_id = top_valid(opp_heap)
            if opp_id is None:
                break
            opp = book[opp_id]
            opp_price = opp['price']

            if typ == 'market':
                can_match = True
            else:
                if side == 'buy':
                    can_match = price >= opp_price
                else:
                    can_match = price <= opp_price

            if not can_match:
                break

            trade_qty = min(remaining, opp['qty'])
            if side == 'buy':
                trades.append([oid, opp_id, opp_price, trade_qty])
            else:
                trades.append([opp_id, oid, opp_price, trade_qty])

            remaining -= trade_qty
            opp['qty'] -= trade_qty

            if opp['qty'] <= 0:
                opp['active'] = False
                heapq.heappop(opp_heap)
            # if opp still has qty left, keep it at top for next iteration (loop will re-check)

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': my_seq, 'active': True}
            push_order(oid)
        elif typ == 'limit' and remaining == 0:
            # fully filled, still record as inactive/filled entry so cancel does nothing
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': my_seq, 'active': False}
        # ioc and market: discard remainder, no need to store (cancel on unknown id does nothing anyway)

    return trades

